//! The dev-mode menu (plan revision: "por enquanto criar menu em branco
//! apenas com o botão voltar", depois: "instalar assets exemplo -
//! demonstrar funcionamento do emulador") — behind the idle panel's "Dev"
//! button, which itself only exists once the Konami code has been entered on
//! the idle screen. Installs the SNES sample game (a synthetic ROM plus its
//! cover/back cover/cartridge/logo art and a manual PDF, all generated by
//! `scripts/gen_example_assets.py` and embedded in the binary) into the app
//! root, so a fresh install has something on the shelf — no network.

use std::path::Path;
use std::time::{Duration, Instant};

use anyhow::Result;
use sixteen_platform::{Cabinet, MenuMode, MenuNav, Platform, Screen};

#[allow(unused_imports)]
use sixteen_platform::tr;

use crate::dirs;

/// O pacote de exemplo embutido: `(caminho relativo à raiz do app, bytes)`.
/// Gerado por `scripts/gen_example_assets.py` — arte, ROM e manual nossos.
const EXAMPLE_FILES: &[(&str, &[u8])] = &[
    (
        "roms/SixteeN Demo Cart.sfc",
        include_bytes!("../assets/example/roms/SixteeN Demo Cart.sfc"),
    ),
    (
        "assets/cover/SixteeN Demo Cart.png",
        include_bytes!("../assets/example/assets/cover/SixteeN Demo Cart.png"),
    ),
    (
        "assets/backcover/SixteeN Demo Cart.png",
        include_bytes!("../assets/example/assets/backcover/SixteeN Demo Cart.png"),
    ),
    (
        "assets/cartridge/SixteeN Demo Cart.png",
        include_bytes!("../assets/example/assets/cartridge/SixteeN Demo Cart.png"),
    ),
    (
        "assets/logo/SixteeN Demo Cart.png",
        include_bytes!("../assets/example/assets/logo/SixteeN Demo Cart.png"),
    ),
    (
        "assets/manual/SixteeN Demo Cart.pdf",
        include_bytes!("../assets/example/assets/manual/SixteeN Demo Cart.pdf"),
    ),
];

const BG: (u8, u8, u8) = (18, 18, 20);
const TEXT: (u8, u8, u8) = (232, 232, 232);
const DIM: (u8, u8, u8) = (150, 150, 158);
const GREEN: (u8, u8, u8) = (60, 230, 70);

/// Same glyph metrics the platform font uses — `Screen::text` advances
/// `GLYPH_W * scale` per char, `GLYPH_H * scale` per line.
const CELL: i32 = 9;

/// The "voltar" button's rect in screen-buffer coordinates — the single
/// source both the draw closure and the click hit-test use (same pattern as
/// the idle setup screen's `setup_rects`).
fn voltar_rect(w: u32, h: u32) -> (i32, i32, u32, u32) {
    let (bw, bh) = (220u32, 44u32);
    (
        (w as i32 - bw as i32) / 2,
        h as i32 - bh as i32 - 52,
        bw,
        bh,
    )
}

/// The "instalar assets de exemplo" button's rect — the menu's one action.
fn install_rect(w: u32, h: u32) -> (i32, i32, u32, u32) {
    let (bw, bh) = (510u32, 44u32);
    (
        (w as i32 - bw as i32) / 2,
        h as i32 / 2 - bh as i32 - 10,
        bw,
        bh,
    )
}

/// O botão de alternar o painel de desempenho ("infos de desempenho"),
/// logo abaixo do de instalar.
fn perf_rect(w: u32, h: u32) -> (i32, i32, u32, u32) {
    let (bw, bh) = (510u32, 44u32);
    ((w as i32 - bw as i32) / 2, h as i32 / 2 + 10, bw, bh)
}

fn in_rect(x: i32, y: i32, r: (i32, i32, u32, u32)) -> bool {
    x >= r.0 && y >= r.1 && (x - r.0) < r.2 as i32 && (y - r.1) < r.3 as i32
}

/// Run the dev menu until the player backs out. Returns `Ok(true)` when the
/// app should quit altogether (window closed here), `Ok(false)` to return to
/// the idle screen — same contract as the settings screen's `run`.
pub fn run(plat: &mut Platform, cab: &mut Cabinet) -> Result<bool> {
    let frame = Duration::from_millis(16);
    let mut next = Instant::now() + frame;

    // Status line under the button — hint while idle, outcome afterwards
    // (kept until the next attempt).
    let mut status = String::from(tr!(
        "installs a SNES sample game with cover, cartridge, back cover and manual",
        "instala um jogo de exemplo de SNES com capa, cartucho, contracapa e manual"
    ));
    let mut status_color = DIM;
    // Seleção (gamepad): 0 = instalar, 1 = infos de desempenho. Clique
    // ativa direto; Confirm/Up/Down andam a seleção.
    let mut sel = 0usize;

    loop {
        let m = plat.poll_menu(MenuMode::Nav);
        if m.quit {
            return Ok(true);
        }
        let mut start = false;
        let mut toggle_perf = false;
        // Confirm ativa o botão SELECIONADO; Up/Down alternam entre os dois.
        for n in &m.nav {
            match n {
                MenuNav::Confirm => {
                    if sel == 0 {
                        start = true;
                    } else {
                        toggle_perf = true;
                    }
                }
                MenuNav::Up | MenuNav::Down => sel = 1 - sel,
                MenuNav::Back => return Ok(false),
                _ => {}
            }
        }
        if let Some((x, y)) = m.click {
            let (ox, oy) = cab.window_to_output(x, y);
            if cab.hit_close_button(ox, oy) {
                return Ok(true);
            }
            if let Some((sx, sy)) = cab.hit_screen_point(ox, oy) {
                let (w, h) = cab.screen_size();
                if in_rect(sx, sy, install_rect(w, h)) {
                    start = true;
                }
                if in_rect(sx, sy, perf_rect(w, h)) {
                    toggle_perf = true;
                }
                if in_rect(sx, sy, voltar_rect(w, h)) {
                    return Ok(false);
                }
            }
        }
        if toggle_perf {
            let on = !cab.perf_overlay();
            cab.set_perf_overlay(on);
            status_color = GREEN;
            status = tr!(
                format!(
                    "performance info {} — shown at the top of the tv during the game",
                    if on { "ON" } else { "OFF" }
                ),
                format!(
                    "infos de desempenho {} — aparece no topo da tv durante o jogo",
                    if on { "LIGADO" } else { "DESLIGADO" }
                )
            );
        }
        if start {
            match install_example(&dirs::app_root()) {
                Ok(n) => {
                    status_color = GREEN;
                    status = tr!(
                        format!("{n} files installed — click refresh on the shelf to see the game"),
                        format!(
                            "instalado! {n} arquivos — clique atualizar na estante para ver o jogo"
                        )
                    );
                }
                Err(e) => {
                    status_color = (240, 120, 110);
                    status = tr!(format!("failed: {e}"), format!("falha: {e}"));
                }
            }
        }

        let status = status.clone();
        let status_color = status_color;
        let sel = sel;
        let perf_on = cab.perf_overlay();
        let render = move |d: &mut Screen| {
            let (w, h) = d.size();
            let (ix, iy, iw, ih) = install_rect(w, h);
            let label = tr!("install example assets", "instalar assets de exemplo");
            // Botão selecionado acende; o outro fica apagado.
            let color = if sel == 0 { TEXT } else { DIM };
            d.outline(ix, iy, iw, ih, 2, (color.0, color.1, color.2, 255));
            d.text(
                ix + (iw as i32 - label.chars().count() as i32 * CELL * 2) / 2,
                iy + (ih as i32 - 40) / 2,
                2,
                color,
                label,
            );
            let (px, py, pw, ph) = perf_rect(w, h);
            let pcolor = if sel == 1 { TEXT } else { DIM };
            let plabel = tr!(
                format!("performance info: {}", if perf_on { "ON" } else { "OFF" }),
                format!(
                    "infos de desempenho: {}",
                    if perf_on { "LIGADO" } else { "DESLIGADO" }
                )
            );
            d.outline(px, py, pw, ph, 2, (pcolor.0, pcolor.1, pcolor.2, 255));
            d.text(
                px + (pw as i32 - plabel.chars().count() as i32 * CELL * 2) / 2,
                py + (ph as i32 - 40) / 2,
                2,
                pcolor,
                &plabel,
            );

            // Uma linha centrada quando cabe (a dica/status são curtos); em
            // tela estreita cai para text_wrapped na margem.
            let single = status.chars().count() as i32 * CELL;
            let status_y = (py + ph as i32).max(iy + ih as i32) + 18;
            if single <= w as i32 - 40 {
                d.text((w as i32 - single) / 2, status_y, 1, status_color, &status);
            } else {
                d.text_wrapped(40, status_y, w - 80, 1, status_color, &status);
            }

            let (bx, by, bw, bh) = voltar_rect(w, h);
            d.outline(bx, by, bw, bh, 2, (TEXT.0, TEXT.1, TEXT.2, 255));
            let label = tr!("back", "voltar");
            d.text(
                bx + (bw as i32 - label.chars().count() as i32 * CELL * 2) / 2,
                by + (bh as i32 - 40) / 2,
                2,
                TEXT,
                label,
            );
        };
        cab.frame_2d(BG, render);
        crate::runner::pace_frame(&mut next, frame);
    }
}

/// Write the embedded sample package into `root` (`roms/` + `assets/`).
/// Idempotent by design: files already there are kept, never overwritten.
fn install_example(root: &Path) -> std::result::Result<usize, String> {
    for (rel, bytes) in EXAMPLE_FILES {
        let dest = root.join(rel);
        // Nunca por cima do que já existe: um demo cart com save/arte
        // editados pelo usuário fica como está (o mesmo do seed em exemplo.rs).
        if dest.exists() {
            continue;
        }
        if let Some(parent) = dest.parent() {
            std::fs::create_dir_all(parent).map_err(|e| e.to_string())?;
        }
        std::fs::write(&dest, bytes).map_err(|e| format!("{}: {e}", dest.display()))?;
    }
    Ok(EXAMPLE_FILES.len())
}

/// Headless preview of the dev menu (dev/testing) — one frame captured
/// through the tube into a BMP, exactly as `run` draws it.
pub fn capture_preview(cab: &mut Cabinet, path: &std::path::Path) -> Result<()> {
    let render = |d: &mut Screen| {
        let (w, h) = d.size();
        let (ix, iy, iw, ih) = install_rect(w, h);
        let label = tr!("install example assets", "instalar assets de exemplo");
        d.outline(ix, iy, iw, ih, 2, (TEXT.0, TEXT.1, TEXT.2, 255));
        d.text(
            ix + (iw as i32 - label.chars().count() as i32 * CELL * 2) / 2,
            iy + (ih as i32 - 40) / 2,
            2,
            TEXT,
            label,
        );
        let hint = tr!(
            "installs a SNES sample game with cover, cartridge, back cover and manual",
            "instala um jogo de exemplo de SNES com capa, cartucho, contracapa e manual"
        );
        d.text(
            (w as i32 - hint.chars().count() as i32 * CELL) / 2,
            iy + ih as i32 + 18,
            1,
            DIM,
            hint,
        );

        let (bx, by, bw, bh) = voltar_rect(w, h);
        d.outline(bx, by, bw, bh, 2, (TEXT.0, TEXT.1, TEXT.2, 255));
        let label = tr!("back", "voltar");
        d.text(
            bx + (bw as i32 - label.chars().count() as i32 * CELL * 2) / 2,
            by + (bh as i32 - 40) / 2,
            2,
            TEXT,
            label,
        );
    };
    cab.capture_2d(BG, render, path)
        .map_err(|e| anyhow::anyhow!(e.to_string()))
}

#[cfg(test)]
mod tests {
    use super::{install_example, EXAMPLE_FILES};

    /// raiz temporária única por teste (sem dep de tempfile)
    fn tempfile_root(tag: &str) -> std::path::PathBuf {
        std::env::temp_dir().join(format!("sixteen-devmenu-test-{}-{tag}", std::process::id()))
    }

    #[test]
    fn install_writes_roms_and_assets_idempotently() {
        let root = tempfile_root("install");
        let n = install_example(&root).unwrap();
        assert_eq!(n, EXAMPLE_FILES.len());
        for sub in ["cover", "backcover", "cartridge", "logo", "manual"] {
            let dir = root.join("assets").join(sub);
            assert_eq!(std::fs::read_dir(&dir).unwrap().count(), 1, "{sub}");
        }
        assert_eq!(std::fs::read_dir(root.join("roms")).unwrap().count(), 1);
        // de novo: não sobrescreve o que o usuário já mexeu
        let rom = root.join("roms").join("SixteeN Demo Cart.sfc");
        std::fs::write(&rom, b"editado").unwrap();
        assert_eq!(install_example(&root).unwrap(), n);
        assert_eq!(std::fs::read(&rom).unwrap(), b"editado");
        std::fs::remove_dir_all(&root).ok();
    }

    #[test]
    fn embedded_rom_has_a_valid_snes_header() {
        let (_, rom) = EXAMPLE_FILES
            .iter()
            .find(|(rel, _)| rel.ends_with(".sfc"))
            .unwrap();
        assert_eq!(rom.len(), 0x8000);
        let h = &rom[0x7FC0..];
        assert_eq!(&h[..17], b"SIXTEEN DEMO CART");
        // complemento + checksum somam 0xFFFF, e o checksum é a soma da ROM
        let comp = u16::from_le_bytes([h[0x1C], h[0x1D]]);
        let sum = u16::from_le_bytes([h[0x1E], h[0x1F]]);
        assert_eq!(comp ^ sum, 0xFFFF);
        let total = rom.iter().map(|&b| b as u32).sum::<u32>() & 0xFFFF;
        assert_eq!(total as u16, sum);
    }
}
